def can_fit_in_lines(words, max_lines, width):
    """Check if words can fit in at most max_lines with given width"""
    lines_needed = 1
    current_width = 0

    for word_width in words:
        if current_width == 0:
            # First word in line - just add width
            if word_width > width:
                return False
            current_width = word_width
        else:
            # Need space after previous word
            if current_width + 1 + word_width > width:
                # Can't fit, need new line
                lines_needed += 1
                current_width = word_width
                if lines_needed > max_lines:
                    return False
            else:
                current_width += 1 + word_width

    return True

