def can_fit(word_widths, M, width):
    """Check if sentence fits in at most M lines with given width"""
    n = len(word_widths)
    lines = 1  # Start with first line
    current_width = 0

    for i in range(n):
        # If first word or current word doesn't fit in current line
        if current_width == 0:
            current_width = word_widths[i]
        else:
            # Try to add next word with gap of 1
            if current_width + 1 + word_widths[i] <= width:
                current_width += 1 + word_widths[i]
            else:
                # Start new line
                lines += 1
                current_width = word_widths[i]

                # Early termination if we exceed M lines
                if lines > M:
                    return False

    return True

def solve():
