class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        # Total ways without limit constraint
        total = (n + 2) * (n + 1) // 2

        # Subtract cases where at least one child gets more than limit
        # Using inclusion-exclusion principle

        # Cases where one child gets more than limit
        one_exceed = 0
        if n > limit:
            # If a child gets more than limit, they get at least (limit + 1)
            # Remaining candies to distribute = n - (limit + 1)
            remaining = n - (limit + 1)
            if remaining >= 0:
                one_exceed = (remaining + 2) * (remaining + 1) // 2
            else:
                one_exceed = 0

        # Cases where two children get more than limit  
        two_exceed = 0
        if n > 2 * (limit + 1):
            remaining = n - 2 * (limit + 1)
            if remaining >= 0:
                two_exceed = (remaining + 2) * (remaining + 1) // 2
            else:
                two_exceed = 0

        # Cases where three children get more than limit
        three_exceed = 0
        if n > 3 * (limit + 1):
            remaining = n - 3 * (limit + 1)
            if remaining >= 0:
                three_exceed = (remaining + 2) * (remaining + 1) // 2
            else:
                three_exceed = 0

        # Apply inclusion-exclusion
        # |A ∪ B ∪ C| = 3*|A| - 3*|A∩B| + |A∩B∩C|
        result = total - 3 * one_exceed + 3 * two_exceed - three_exceed

        return result

